/**
 * Applies the Prisma schema SQL to a remote Turso / libSQL database.
 * Run with: bun /home/z/my-project/scripts/apply-schema-turso.ts
 *
 * Reads:
 *  - DATABASE_URL from .env (must start with libsql://)
 *  - DATABASE_AUTH_TOKEN from .env
 *  - schema SQL from /tmp/schema.sql (generated by `prisma migrate diff`)
 */
import { createClient } from '@libsql/client'
import * as fs from 'fs'

const url = process.env.DATABASE_URL
const authToken = process.env.DATABASE_AUTH_TOKEN

if (!url || !url.startsWith('libsql://')) {
  console.error(`DATABASE_URL must be set to a libsql:// URL (got: ${url})`)
  process.exit(1)
}
if (!authToken) {
  console.error('DATABASE_AUTH_TOKEN must be set')
  process.exit(1)
}

const sqlFile = '/tmp/schema.sql'
if (!fs.existsSync(sqlFile)) {
  console.error(`Schema SQL file not found: ${sqlFile}`)
  process.exit(1)
}

const sql = fs.readFileSync(sqlFile, 'utf8')

async function main() {
  const client = createClient({ url, authToken })

  // Split the SQL on statement boundaries (lines that end with ;)
  const statements = sql
    .split(/;\s*\n/)
    .map((s) => s.trim())
    .filter((s) => s.length > 0)
    // Strip leading comment lines like "-- CreateTable"
    .map((s) => s.replace(/^--[^\n]*\n/, '').trim())
    .filter((s) => s.length > 0)

  console.log(`Connected to ${url}`)
  console.log(`Applying ${statements.length} SQL statements...`)

  for (let i = 0; i < statements.length; i++) {
    const stmt = statements[i]
    const label = stmt.split('\n')[0].slice(0, 80)
    try {
      await client.execute(stmt)
      console.log(`  ${i + 1}/${statements.length} OK: ${label}...`)
    } catch (e: any) {
      // Ignore "table already exists" errors — useful for re-running
      if (e.message.includes('already exists') || e.message.includes('duplicate')) {
        console.log(`  ${i + 1}/${statements.length} SKIP (already exists): ${label}...`)
      } else {
        console.error(`  ${i + 1}/${statements.length} FAIL: ${label}`)
        console.error(`    ${e.message}`)
      }
    }
  }
  console.log('Done.')
}

main().catch((e) => {
  console.error(e)
  process.exit(1)
})
